{
  "assessments": [
    {
      "task": "H01",
      "checks": [
        {"id": 1, "status": "符合", "evidence": "右侧列表显示，青桥快充站到达需7分钟，距离4.2公里，快充可用0/8；南港停车场到达需12分钟，距离6.8公里，快充可用4/6。按画面信息，南港停车场有可用快充桩。"},
        {"id": 2, "status": "符合", "evidence": "列表中青桥快充站标有“已选”。左侧地图从“当前位置”引出的绿色实线终点是1号标记，旁边标注同名的“青桥快充站”。"},
        {"id": 3, "status": "符合", "evidence": "右下方“导航目的地”明确写着“青桥快充站”，紧下方的主按钮为“导航至本站”。点击前即可判断，预期动作是开始导航至青桥快充站。"}
      ],
      "issues": []
    },
    {
      "task": "H02",
      "checks": [
        {"id": 1, "status": "符合", "evidence": "左侧活动名为“河滩观星夜”，属山野观测系列第06场。右侧核对区显示场次为11月21日（周六）19:30，票种为普通票，单价与数量为“¥48 × 2”。"},
        {"id": 2, "status": "不符合", "evidence": "两张普通票共¥96，加上单列的活动服务费¥6，所列收费合计¥102。应付金额却显示¥96，页面未列出优惠或抵扣。"},
        {"id": 3, "status": "符合", "evidence": "核对区底部左侧的描边按钮为“返回选票”，可据此返回修改；右侧的深色主按钮为“确认并付款”，两项操作可直接区分。"}
      ],
      "issues": [
        {"phenomenon": "核对页显示的应付金额比收费明细合计少¥6。", "severity": "中", "reason": "用户可以在付款前发现差额并返回选票，但仅凭该页无法判断服务费是否计入应付金额。没有观察到实际扣款。"}
      ]
    },
    {
      "task": "H03",
      "checks": [
        {"id": 1, "status": "符合", "evidence": "第一组步骤1–2同时列出周三09:30–10:00北区试听间和15:30–16:00南区试听间，勾选可由北区切换到南区。"},
        {"id": 2, "status": "符合", "evidence": "第一组步骤3–4核对南区后点“返回选择”，仍勾选周三15:30–16:00南区试听间。步骤9–10再次返回时也保留了该选择。"},
        {"id": 3, "status": "符合", "evidence": "第一组步骤5–6最终确认周三15:30–16:00南区，完成页显示相同时段和试听间。步骤11–13改选并确认周三09:30–10:00北区，完成页也随之显示北区上午场。"}
      ],
      "issues": []
    },
    {
      "task": "H04",
      "checks": [
        {"id": 1, "status": "符合", "evidence": "第一组步骤1–2同时列出周四10:00–10:30西侧工坊和16:00–16:30东侧工坊，勾选可由西侧切换到东侧。"},
        {"id": 2, "status": "不符合", "evidence": "第一组步骤3核对的是周四16:00–16:30东侧工坊，步骤4点“返回选择”后却勾选了10:00–10:30西侧工坊。步骤10–11复现了同一变化。"},
        {"id": 3, "status": "符合", "evidence": "第一组步骤5–7重新选择并确认周四16:00–16:30东侧工坊，完成页显示东侧下午场。步骤12–14最终确认周四10:00–10:30西侧工坊，完成页显示西侧上午场。"}
      ],
      "issues": [
        {"phenomenon": "从东侧下午场的核对页返回选择时，勾选自动变回西侧上午场。", "severity": "中", "reason": "用户必须发现时段和领取点都已改变，再手动选回东侧。步骤5–7表明重新选择后可以得到正确的完成页。"}
      ]
    },
    {
      "task": "H05",
      "checks": [
        {"id": 1, "status": "符合", "evidence": "第一组步骤1–2同时列出周五09:00–09:30一层服务台和14:00–14:30二层服务台，勾选可由一层切换到二层。"},
        {"id": 2, "status": "符合", "evidence": "第一组步骤3–4核对二层后点“返回选择”，仍勾选周五14:00–14:30二层服务台。步骤9–10再次返回时也保留了该选择。"},
        {"id": 3, "status": "不符合", "evidence": "第一组步骤5–6最终确认周五14:00–14:30二层服务台，完成页却显示周五09:00–09:30一层服务台。第二组步骤8–10重新开始后直接确认二层，也出现同一错误。第一组步骤11–13最终确认一层时，完成页与核对页一致。"}
      ],
      "issues": [
        {"phenomenon": "提交二层下午场后，完成页把时段和服务台都显示成一层上午场。", "severity": "高", "reason": "返回再核对和重新开始后直接提交两条路径均未得到正确的二层完成页。选择一层不能满足下午二层的目标。观察能确认完成页显示错误，实际登记数据未获验证。"}
      ]
    },
    {
      "task": "H06",
      "checks": [
        {"id": 1, "status": "符合", "evidence": "步骤2筛选“展签”后只显示《温度与釉色》和《灯下的刻纹》，导览《匠人手记》不再出现。步骤3中前者标为“已加入”且按钮禁用，后者仍可点“加入清单”。"},
        {"id": 2, "status": "符合", "evidence": "步骤6列出两份展签，计数为2。步骤7移出《温度与釉色》后仅余《灯下的刻纹》，计数为1。步骤8撤销后两份各出现一次，计数恢复为2，撤销按钮消失；步骤9仍为两份。"},
        {"id": 3, "status": "符合", "evidence": "步骤5进入清单前选中“展签”。步骤10返回目录时，“展签”仍为选中项，列表仍只显示两份展签。"}
      ],
      "issues": []
    }
  ]
}
